supplementary_probe_sources.cache_and_layout_rust:
use rethoc_engine::{MatcherMemory, Regex, RegexConfig};

fn main() {
    println!("Regex={} MatcherMemory={}", std::mem::size_of::<Regex>(), std::mem::size_of::<MatcherMemory>());
    for pattern in ["foo", r"\bfoo\b", r"(?m)^foo$", r"foo$", r"\bfoo\b(?m:$)", r"(?Rm)^foo$"] {
        let regex = Regex::new(pattern).unwrap();
        let mut memory = MatcherMemory::default();
        println!("pattern={pattern:?} memory={} tier1={}", regex.memory_size(), memory.matcher_for_tier(&regex, 1).is_ok());
    }
    let cases: &[(&str, &str, &[u8])] = &[
        ("literal", "foo", b"fxfx bar "),
        ("word", r"\bfoo\b", b" fooX !fooX \n\r"),
        ("endlf", r"foo(?m:$)", b"fooX\r\n"),
        ("endlf_context", r".(?m:$)", b"word space \r \xff"),
        ("mixed", r"\bfoo\b(?m:$)", b" fooX !fooX \n\r"),
        ("churn", r"[ab]*a[ab]{5}z", b"aaaaaabaaaabbaababababbbabbbbbb"),
    ];
    for &(name, pattern, repeated) in cases {
        for classes in [false, true] {
            let regex = Regex::with_config(pattern, RegexConfig { byte_class_min_states: if classes { 0 } else { usize::MAX }, ..RegexConfig::default() }).unwrap();
            for cap in [None, Some(8)] {
                let mut memory = MatcherMemory::default();
                memory.set_dfa_state_cap(cap);
                let input: Vec<_> = repeated.iter().copied().cycle().take(16 * 1024).collect();
                for pass in 0..2 {
                    let mut matcher = memory.matcher_for_tier(&regex, 1).unwrap();
                    matcher.chunk(&input);
                    let matched = matcher.finish();
                    println!("CACHE name={name} classes={classes} cap={cap:?} pass={pass} matched={matched} {memory:?}");
                }
            }
        }
    }
}

supplementary_probe_sources.peak_rss_c:
#include <stdio.h>
#include <stdlib.h>
#include <sys/resource.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
int main(int argc, char **argv) {
    if (argc < 2) return 2;
    pid_t pid = fork();
    if (pid == -1) return 2;
    if (pid == 0) {
        execv(argv[1], argv + 1);
        _exit(127);
    }
    int status;
    struct rusage usage;
    if (wait4(pid, &status, 0, &usage) == -1) return 2;
    fprintf(stderr, "PEAK_RSS_KIB=%ld\n", usage.ru_maxrss);
    return WIFEXITED(status) ? WEXITSTATUS(status) : 128 + WTERMSIG(status);
}
